import os
import re
import logging
import psycopg2
from Bio import Entrez

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def extract_data(filepath):
    try:
        with open(filepath, 'r') as f:
            text = f.read()
        gene_pattern = r'(\w+)\s+(\d+\.?\d*)'
        matches = re.findall(gene_pattern, text)
        return matches
    except Exception as e:
        logging.error(f"Error reading or parsing file {filepath}: {e}")
        return []

def validate_gene_id(gene_symbol):
    Entrez.email = "your_email@example.com"  # Replace with your email
    try:
        handle = Entrez.esearch(db="gene", term=gene_symbol, retmax=1)
        record = Entrez.read(handle)
        handle.close()
        if record["Count"] > 0:
            return True
        else:
            return False
    except Exception as e:
        logging.error(f"Error validating gene ID {gene_symbol}: {e}")
        return False

def load_data_to_db(data, db_host, db_name):
    try:
        conn = psycopg2.connect(host=db_host, database=db_name)
        cur = conn.cursor()
        for gene_symbol, expression_value in data:
            if validate_gene_id(gene_symbol):
                cur.execute("INSERT INTO gene_expression (gene_symbol, expression_value) VALUES (%s, %s)", (gene_symbol, expression_value))
            else:
                logging.warning(f"Skipping invalid gene ID: {gene_symbol}")
        conn.commit()
        cur.close()
        conn.close()
    except psycopg2.Error as e:
        logging.error(f"Database error: {e}")

def main():
    input_directory = "./expression_logs/"
    gene_id_list_path = "hgnc_ids.txt"
    db_host = "localhost"
    db_name = "expression_db"

    # Load gene IDs from file
    try:
        with open(gene_id_list_path, 'r') as f:
            gene_ids = [line.strip() for line in f]
    except FileNotFoundError:
        logging.error(f"Gene ID list file not found: {gene_id_list_path}")
        return
    except Exception as e:
        logging.error(f"Error reading gene ID list: {e}")
        return

    for filename in os.listdir(input_directory):
        if filename.endswith(".txt"):
            filepath = os.path.join(input_directory, filename)
            data = extract_data(filepath)
            if data:
                load_data_to_db(data, db_host, db_name)
            else:
                logging.warning(f"No data extracted from {filename}")

if __name__ == "__main__":
