```python
import os
import re
import vcf

def validate_vcf_files(input_directory, target_standard, valid_bases, chromosome_formats):
    """
    Validates and reformats VCF files for EGA submission.

    Args:
        input_directory (str): Path to the directory containing VCF files.
        target_standard (str): Target submission standard (for reporting).
        valid_bases (list): List of valid DNA bases.
        chromosome_formats (list): List of acceptable chromosome formats.

    Returns:
        tuple: A tuple containing a list of valid files and a dictionary of errors.
    """

    valid_files = []
    errors = {}

    for filename in os.listdir(input_directory):
        if filename.endswith(".vcf.gz") or filename.endswith(".vcf"):
            filepath = os.path.join(input_directory, filename)
            try:
                vcf_file = vcf.Reader.from_path(filepath)
                header = vcf_file.header

                # Check header validity (basic check - more robust checks could be added)
                if not header.info:
                    errors[filename] = {"line": "Header is empty", "type": "HeaderError"}
                    continue

                # Validate chromosome names
                for record in vcf_file:
                    chrom = record.chrom
                    if chrom not in chromosome_formats:
                        chrom = re.sub(r'[^0-9a-zA-Z]', '', chrom)  # Remove non-alphanumeric chars
                        if chrom not in chromosome_formats:
                            errors[filename] = {
                                "line": record.line.strip(),
                                "type": "ChromosomeFormatError",
                                "message": f"Invalid chromosome format: {chrom}.  Must be 'chr1' or '1'."
                            }
                            break  # Stop checking chromosome after first error

                    # Validate REF and ALT alleles
                    for record in vcf_file:
                        ref = record.ref
                        alt = record.alt
                        for base in ref:
                            if base not in valid_bases:
                                errors[filename] = {
                                    "line": record.line.strip(),
                                    "type": "BaseValidationError",
                                    "message": f"Invalid REF base: {base}.  Must be A, C, G, or T."
                                }
                                break
                        for base in alt:
                            if base not in valid_bases:
                                errors[filename] = {
                                    "line": record.line.strip(),
                                    "type": "BaseValidationError",
                                    "message": f"Invalid ALT base: {base}.  Must be A, C, G, or T."
                                }
                                break
                    break # Break inner loop after finding an error

                if filename not in errors:
                    valid_files.append(filename)

            except Exception as e:
                errors[filename] = {"line": "VCF parsing error", "type": "VCFError", "message": str(e)}

    return valid_files, errors


if __name__ == "__main__":
    input_directory = "./vcf_files/"
    target_standard = "EGA Submission Guidelines"
    valid_bases = ["A", "C", "G", "T"]
    chromosome_formats = ["chr1", "1"]

    valid_files, errors = validate_vcf_files(input_directory, target_standard, valid_bases, chromosome_formats)

    print("Valid Files:")
    for file in valid_files:
        print(file)

    print("\nErrors:")
    for filename, error_details in errors.items():
        print(f"File: {filename}")
        print(f"  Line: {error_details['line']}")
        print(f"  Type: {error_details['type']}")
        print(f"  Message: {error_details['message']}")
